export interface RebusCropBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface RebusChallenge {
  id: string;
  postId: number;
  title: string;
  postDate: string;
  postUrl: string;
  category: string;
  difficulty: 'Standard' | 'Medium' | 'Challenging';
  imageUrl: string | null;
  cropBox?: RebusCropBox;
  pdfUrl?: string;
  textRebus: string | null;
  prompt: string;
  wordPattern: number[];
  firstLetters: string;
  blogClue: string;
  answer: string;
  acceptedAnswers: string[];
  explanation: string;
  source?: 'Puzzle a Day' | 'Just Family Fun';
}

export interface WorksheetGridItem {
  index: number;
  answer: string;
  acceptedAnswers?: string[];
  wordPattern: number[];
  firstLetters: string;
  clue: string;
  explanation: string;
}

export interface WorksheetPdfLink {
  label: string;
  url: string;
}

export interface WorksheetGrid {
  id: string;
  postId: number;
  title: string;
  postDate: string;
  postUrl: string;
  source?: 'Puzzle a Day' | 'Just Family Fun';
  collection?: string;
  pdfUrls?: WorksheetPdfLink[];
  imageUrls: string[];
  totalCount: number;
  items: WorksheetGridItem[];
}

export interface PdfLibraryGroup {
  group: string;
  items: {
    title: string;
    url: string;
    count: string;
    worksheetId?: string;
  }[];
}

